    ("02-music-control.svg", "MUSIC & AMBIENCE", "Musik ikut hidup", "Kontrol media sistem dari satu panel. Saat lagu berjalan, BRAMO ikut bergoyang dan mulutnya humming.", "Beat-nya enak nih 🎵", "NOW PLAYING", ["SYSTEM MEDIA", "AUTO DETECT", "VIBE MODE"], [("KONTROL MEDIA", "Sebelumnya, play/pause, dan berikutnya."), ("NOW PLAYING", "Judul, artis, dan status pemutaran."), ("MUSIC VIBE", "Equalizer eyes, glow, groove, humming.")]),
    ("03-focus-pomodoro.svg", "FOCUS WITH A FRIEND", "Fokus bareng BRAMO", "Atur sesi fokus dan istirahat. Mini timer tetap terlihat, sementara BRAMO menemani dengan dukungan singkat.", "Fokus dimulai. BRAMO jagain 😎", "POMODORO", ["MINI TIMER", "XP REWARD", "FOCUS BUDDY"], [("DURASI FLEKSIBEL", "Sesi fokus 15, 25, 45, atau 60 menit."), ("FOCUS + BREAK", "Atur durasi istirahatmu sendiri."), ("APRESIASI", "Target 2, 4, dan 6 sesi fokus harian.")]),
    ("04-tools-launcher.svg", "EVERYDAY TOOLS", "Tools cepat di satu tempat", "Panel dropdown mengumpulkan utilitas desktop untuk cek sistem, buka shortcut, serta memindahkan file dan clipboard.", "Beres, file-nya sudah mendarat 📁", "QUICK TOOLS", ["CPU / RAM / BATTERY", "FILE HISTORY", "SHORTCUTS"], [("SYSTEM STATS", "Pantau CPU, RAM, dan baterai."), ("FILE DROP", "Buka file atau tunjukkan lokasinya."), ("LAUNCHER + CLIPBOARD", "Shortcut aplikasi/web dan watcher opsional.")]),
    ("05-break-prayer.svg", "HEALTH & REMINDERS", "Ingat jeda dan waktu penting", "Pengingat jeda membantu rehat dari layar. Jadwal salat dan audio azan punya panel, tombol tes, dan kontrol mute.", "Waktunya jeda sebentar 🌿", "REMINDERS", ["BREAK TIMER", "PRAYER TIMES", "AUDIO CONTROL"], [("BIO-RHYTHM", "Jeda berkala, selesai, atau tunda."), ("PRAYER REMINDER", "Jadwal salat berbasis lokasi."), ("AZAN PRIORITY", "Prioritaskan reminder dan atur audio.")]),
    ("06-visor-collection.svg", "PERSONALIZATION & XP", "Buka gaya baru sambil berprogres", "Interaksi memberi XP. Naik level membuka aksesori dan kosmetik visor, sementara mood serta sapaan memberi sentuhan personal.", "+12 XP — Level up! ✨", "BRAMO JOURNEY", ["XP HISTORY", "ACCESSORIES", "VISOR THEMES"], [("XP + LEVEL", "Poin, progres level, dan riwayat."), ("KOLEKSI", "Aksesori, mata, mulut, dan glow."), ("4 TEMA VISOR", "Cyan, Matrix, Neon Pink, Amber.")]),
    ("07-living-animations.svg", "A LIVING LED FACE", "Ekspresi kecil, terasa hidup", "BRAMO bereaksi lewat tatapan, mulut LED, glow, dan gerak kapsul — dari penasaran saat mengetik sampai pusing saat digoyang.", "Jangan digoyang terus, pusing 🤕", "BUDDY MODE", ["EXPRESSIVE EYES", "LED MOUTH", "BODY MOTION"], [("PENASARAN + IDLE", "Melirik, mikir, nguap, lalu tenang."), ("SHAKE REACTION", "Mata spiral dan badan mengikuti arah."), ("MOOD + MUSIC", "Sapa, setuju, kaget, semangat, humming.")]),
